function saveCert(){void run(async()=>{const {id,...body}=cert.value;const payload:Row={...body};if(!id)delete payload.version;await props.api('certificates'+(id?'/'+id:''),id?'PUT':'POST',payload);cert.value=freshCert();notice.value='֤�������ѱ��棻�Զ�ǩ����ɾ��������ȷ�ϡ�';await reload();emit('changed')})}
