<p v-if="cert.provider!=='manual'" class="muted">������뼴ͬ�� Let's Encrypt ����Э�飬��ȷ������Ȩ������������</p><button class="primary" :disabled="busy">{{cert.id?'����֤���޸�':cert.provider==='manual'?'��֤������':'���һ������'}}</button><button v-if="cert.id" type="button" class="secondary" @click="cert=freshCert()">ȡ���༭</button></form>
<div class="certificate-list" aria-label="����֤���б�"><article v-for="c in certificates" :key="c.id" class="certificate-record"><div class="certificate-identity"><strong>{{c.domain}}</strong><small class="block-muted">{{({cloudflare:'Cloudflare DNS-01','http-01':'HTTP-01',manual:'�ֶ�����'} as Row)[c.provider]||c.provider}}</small></div><div class="certificate-status"><span class="certificate-badge" :class="c.state">{{certState(c)}}</span><small class="block-muted">{{c.expires_at?'���� '+new Date(c.expires_at).toLocaleDateString():c.state==='failed'?'��չ��ǩ������': '�ȴ���Ч�ڻر�'}}</small></div><div v-if="!c.deleted_at" class="certificate-actions"><button class="text-button" @click="editCert(c)">�༭֤��</button><button v-if="c.state==='ready'" class="text-button" @click="prepareProxy(c)">������վ����</button><button v-if="c.provider!=='manual'" class="text-button" :disabled="busy||['running','pending'].includes(c.state)" @click="retry(c)">���� / ����</button><button class="text-button danger" @click="removing={...c,kind:'certificates'}">ɾ��</button></div><details v-if="c.result" class="certificate-result"><summary>ǩ�� / ͬ������</summary><pre>{{c.result}}</pre></details></article><p v-if="!certificates.length" class="muted">��δ��������֤�顣</p></div></template>
